from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def solution(tree):
    root = build(tree)
    if root is None:
        return []
    view = []
    queue = deque([root])
    while queue:
        size = len(queue)              # the queue holds exactly one level
        for _ in range(size):
            node = queue.popleft()
            if node.left is not None:  # left before right, so the last pop is rightmost
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
        view.append(node.val)          # last node popped on this level
    return view
